"""Aviation operations visual language for the Streamlit dashboard."""


def get_global_css() -> str:
    return """
    <style>
    .stApp {background:radial-gradient(circle at 18% 0%,#17385a 0,transparent 28%),linear-gradient(180deg,#0b1220,#070c16);color:#e5e7eb}
    .block-container {max-width:1480px;padding-top:1.25rem;padding-bottom:2.5rem}
    section[data-testid='stSidebar'] {display:none}
    header[data-testid='stHeader'] {background:transparent}
    .top-brand{display:flex;align-items:center;gap:1rem;min-height:92px;padding:1rem 1.25rem;border:1px solid rgba(56,189,248,.28);border-radius:18px 0 0 18px;background:linear-gradient(115deg,#12233b,#0c1626)}
    .top-brand .brand-plane{width:46px;height:46px;margin:0;flex:0 0 auto}.top-brand h1{margin:.15rem 0 0;color:#f8fafc;font-size:2rem;line-height:1}.top-brand h1 span{color:#38bdf8}.top-brand p{margin:.35rem 0 0;color:#94a3b8;font-size:.82rem}
    .header-aircraft{min-height:92px;display:flex;flex-direction:column;justify-content:center;padding:1rem 1.2rem;border-top:1px solid rgba(56,189,248,.28);border-bottom:1px solid rgba(56,189,248,.28);background:#0d1929}.header-aircraft small{color:#7dd3fc;font-size:.65rem;letter-spacing:.12em}.header-aircraft strong{margin-top:.25rem;color:#f8fafc}.header-aircraft span{margin-top:.2rem;color:#94a3b8;font-size:.75rem}
    div[data-testid='stPopover']>button{min-height:92px!important;border-radius:0 18px 18px 0!important;border-color:rgba(56,189,248,.28)!important;background:#0d1929!important;color:#7dd3fc!important}
    .st-key-open_scenario_data button{min-height:92px!important;border-radius:0!important;border-color:rgba(56,189,248,.28)!important;background:#0d1929!important;color:#bae6fd!important}
    .st-key-scenario_actions{position:fixed;left:50%;bottom:1rem;transform:translateX(-50%);width:min(84vw,1380px);z-index:999;padding:.85rem 1rem;background:rgba(9,17,30,.97);border:1px solid rgba(56,189,248,.28);border-radius:14px;box-shadow:0 -12px 30px rgba(0,0,0,.28);backdrop-filter:blur(12px)}
    .st-key-scenario_actions [data-testid='stHorizontalBlock']{align-items:center}
    .section-label{margin-top:.2rem;color:#7dd3fc;font-size:.7rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase}
    .kpi-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1rem;margin:1.3rem 0 1.8rem}.kpi-tile{box-sizing:border-box;display:grid;grid-template-rows:auto 1fr auto;min-height:154px;padding:1.15rem 1.25rem;border:1px solid #263244;border-radius:16px;background:linear-gradient(145deg,#142238,#0e1828);box-shadow:0 8px 24px rgba(0,0,0,.14)}.kpi-tile>span{color:#a8b5c8;font-size:.82rem;font-weight:650}.kpi-tile>strong{align-self:center;color:#f8fafc;font-size:1.75rem;line-height:1.1;letter-spacing:-.035em;white-space:nowrap}.kpi-tile>small{min-height:1.25rem;color:#94a3b8;font-size:.74rem}.kpi-tile .tone-info{color:#7dd3fc}.kpi-tile .tone-safe{color:#86efac}.kpi-tile .tone-warning{color:#fcd34d}.kpi-tile .tone-danger{color:#fca5a5}.kpi-analysis{background:linear-gradient(145deg,rgba(20,43,65,.98),rgba(14,24,40,.98))}
    .hero-card,.deck-shell,.cg-card {box-sizing:border-box;color:#e5e7eb}.hero-card {position:relative;overflow:hidden;display:flex;justify-content:space-between;align-items:center;gap:2rem;padding:2rem 2.25rem;border:1px solid rgba(56,189,248,.28);border-radius:22px;background:linear-gradient(115deg,#12233b,#0c1626 65%,#101d30);box-shadow:0 18px 44px rgba(0,0,0,.25)}
    .eyebrow {color:#7dd3fc;font-size:.72rem;font-weight:800;letter-spacing:.15em;text-transform:uppercase}.signal-dot{display:inline-block;width:7px;height:7px;margin-right:7px;border-radius:50%;background:#22c55e;box-shadow:0 0 12px #22c55e}.hero-card h1{position:relative;margin:.3rem 0;font-size:2.7rem;letter-spacing:-.06em}.hero-card h1 span{color:#38bdf8}.hero-card p{position:relative;margin:0;color:#94a3b8;max-width:44rem}.hero-aircraft{position:relative;min-width:180px;text-align:right}.hero-aircraft small{display:block;margin-top:.35rem;color:#94a3b8}.brand-plane{display:block;width:54px;height:54px;margin:0 0 .5rem auto;fill:#38bdf8}.hero-orbit{position:absolute;border:1px solid rgba(56,189,248,.13);border-radius:50%}.hero-orbit-one{width:360px;height:360px;right:-100px;top:-210px}.hero-orbit-two{width:560px;height:560px;right:-220px;top:-300px}
    div[data-testid='stMetric']{background:linear-gradient(145deg,#142238,#0e1828);border:1px solid #263244;border-radius:15px;padding:1rem 1.1rem;box-shadow:0 8px 24px rgba(0,0,0,.14)}div[data-testid='stMetricLabel']{color:#94a3b8}div[data-testid='stMetricValue']{color:#f8fafc;font-weight:750}.status-pill{display:inline-flex;gap:.45rem;align-items:center;border-radius:999px;padding:.42rem .72rem;font-size:.75rem;font-weight:700;letter-spacing:.03em}.status-pill b{font-size:.69rem}.status-icon{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:5;stroke-linecap:round;stroke-linejoin:round}.status-safe{color:#d1fae5;background:rgba(34,197,94,.14);border:1px solid rgba(34,197,94,.45)}.status-warning{color:#fef3c7;background:rgba(245,158,11,.14);border:1px solid rgba(245,158,11,.45)}.status-danger{color:#fee2e2;background:rgba(239,68,68,.14);border:1px solid rgba(239,68,68,.45)}
    .deck-shell,.cg-card{padding:1.35rem;border:1px solid #263244;border-radius:18px;background:linear-gradient(145deg,#101d30,#0c1523);box-shadow:0 12px 30px rgba(0,0,0,.16)}.deck-heading,.cg-heading{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start;margin-bottom:1rem}.deck-heading h3,.cg-heading h3{margin:.2rem 0 0;color:#e5e7eb}.deck-legend{font-size:.75rem;color:#94a3b8}.deck-legend span{display:inline-block;width:8px;height:8px;margin:0 4px 0 10px;border-radius:50%}.legend-general{background:#38bdf8}.legend-warning{background:#f59e0b}.legend-danger{background:#fb7185}.direction{text-align:center;color:#94a3b8;font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;margin:.5rem 0}.direction svg{width:14px;height:14px;margin-right:5px;vertical-align:-2px;fill:currentColor}.direction-aft{transform:rotate(180deg)}.fuselage{position:relative;padding:1.25rem 2rem;border:1px solid rgba(148,163,184,.2);border-radius:40% 40% 18% 18% / 10% 10% 8% 8%;background:rgba(4,10,20,.42)}.centerline{position:absolute;left:50%;top:2rem;bottom:1.3rem;width:1px;background:rgba(56,189,248,.24)}.deck-grid{position:relative;display:flex;flex-direction:column;gap:.62rem}.deck-row{position:relative}.deck-row-label{position:relative;z-index:2;width:max-content;margin:0 auto .3rem;padding:.12rem .48rem;border-radius:999px;background:#0b1626;color:#64748b;font-size:.58rem;font-weight:800;letter-spacing:.13em}.deck-row-bays{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}.deck-bay{position:relative;display:flex;flex-direction:column;min-height:112px;padding:.8rem;border:1px solid rgba(56,189,248,.28);border-radius:12px;background:linear-gradient(145deg,#172941,#112139)}.deck-bay header{display:flex;justify-content:space-between;gap:.5rem;font-size:.7rem;color:#7dd3fc;font-weight:800;letter-spacing:.08em}.deck-bay header i{color:#64748b;font-style:normal;font-weight:650}.deck-bay strong{margin-top:.45rem}.deck-bay>span,.deck-bay small{margin-top:.2rem;color:#94a3b8;font-size:.76rem}.deck-bay em{position:absolute;right:.65rem;bottom:.55rem;color:#bae6fd;font-size:.65rem;font-style:normal}.bay-flammable,.bay-toxic{border-color:rgba(251,113,133,.55);background:linear-gradient(145deg,#3a1c2e,#221524)}.bay-lithium,.bay-warning{border-color:rgba(245,158,11,.55);background:linear-gradient(145deg,#332815,#211b12)}.is-empty{opacity:.62;border-style:dashed}
    .bay-legal{border-color:rgba(34,197,94,.85)!important;background:linear-gradient(145deg,#0c2a1c,#081c15)!important;box-shadow:0 0 16px rgba(34,197,94,.22)!important;opacity:1!important;border-style:solid!important}
    .bay-illegal{border-color:rgba(239,68,68,.75)!important;background:linear-gradient(145deg,#2e111a,#1e0b12)!important;opacity:.88!important;border-style:solid!important}
    .bay-occupied{border-color:rgba(100,116,139,.55)!important;background:linear-gradient(145deg,#162030,#101724)!important;border-style:solid!important}
    .bay-assigned-current{border-color:rgba(56,189,248,.95)!important;box-shadow:0 0 18px rgba(56,189,248,.32)!important;border-style:solid!important}
    .bay-guidance-badge{display:inline-block;padding:2px 7px;border-radius:6px;font-size:.64rem;font-weight:750;letter-spacing:.03em;margin-top:5px;width:max-content}
    .guidance-legal{background:rgba(34,197,94,.2);color:#86efac;border:1px solid rgba(34,197,94,.5)}
    .guidance-illegal{background:rgba(239,68,68,.2);color:#fca5a5;border:1px solid rgba(239,68,68,.5)}
    .guidance-occupied{background:rgba(148,163,184,.18);color:#cbd5e1;border:1px solid rgba(148,163,184,.35)}
    .domain-card{background:linear-gradient(145deg,#122238,#0c1626);border:1px solid #284462;border-radius:15px;padding:1.1rem 1.25rem;margin:.5rem 0 1rem;box-shadow:0 8px 24px rgba(0,0,0,.18)}
    .domain-title{font-size:.72rem;font-weight:800;letter-spacing:.14em;color:#7dd3fc;text-transform:uppercase;margin-bottom:.4rem}
    .domain-formula{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;font-size:1.15rem;color:#38bdf8;margin:.2rem 0 .6rem;font-weight:700}
    .domain-reason-list{font-size:.78rem;color:#94a3b8;line-height:1.6;margin:0;padding-left:1.1rem}
    .domain-chip{display:inline-flex;align-items:center;padding:3px 9px;border-radius:7px;margin:2px 4px 2px 0;font-family:ui-monospace,monospace;font-size:.8rem;font-weight:700}
    .chip-legal{background:rgba(34,197,94,.22);color:#86efac;border:1px solid rgba(34,197,94,.45)}
    .chip-blocked{background:rgba(239,68,68,.18);color:#fca5a5;border:1px solid rgba(239,68,68,.4);text-decoration:line-through}
    .plan-summary-box{background:linear-gradient(145deg,#101e30,#0b1524);border:1px solid #22374e;border-radius:14px;padding:1rem 1.15rem;margin-bottom:1rem}
    .cg-reading{font-weight:800;color:#e5e7eb}.cg-reading span{display:block;margin-top:.15rem;font-size:.72rem;font-weight:600}.cg-safe span{color:#86efac}.cg-danger span{color:#fca5a5}.cg-scale{position:relative;height:18px;margin:2.6rem .6rem 1.4rem;border-radius:99px;background:#09111e}.cg-safe-band{position:absolute;inset:0;border-radius:99px;background:linear-gradient(90deg,rgba(34,197,94,.45),rgba(56,189,248,.52),rgba(34,197,94,.45))}.cg-marker,.cg-target{position:absolute;top:-12px;transform:translateX(-50%);text-align:center;white-space:nowrap;font-size:.68rem;color:#94a3b8}.cg-marker i,.cg-target i{display:block;width:14px;height:14px;margin:0 auto 3px;border:3px solid #38bdf8;border-radius:50%;background:#f8fafc;box-shadow:0 0 0 4px rgba(56,189,248,.16)}.cg-target i{border-color:#f59e0b;background:#111827}.cg-danger i{border-color:#fb7185}.cg-labels{display:flex;justify-content:space-between;color:#94a3b8;font-size:.7rem}
    div.stButton>button{border-radius:11px;font-weight:750;min-height:43px}div[data-baseweb='tab-list']{gap:.5rem}div[data-testid='stDataFrame'],div[data-testid='stDataEditor']{border:1px solid #263244;border-radius:14px;overflow:hidden}div[data-testid='stVerticalBlockBorderWrapper']{border-color:#263244!important;background:rgba(12,21,35,.65)}
    @media(max-width:1100px){.kpi-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.kpi-tile{min-height:138px}}
    @media(max-width:700px){.top-brand{border-radius:16px}.header-aircraft{border:1px solid rgba(56,189,248,.28);border-radius:16px}.kpi-grid{grid-template-columns:1fr}.hero-card,.deck-heading,.cg-heading{display:block}.hero-aircraft{text-align:left;margin-top:1rem}.fuselage{padding:1rem .7rem}.deck-row-bays{grid-template-columns:1fr}.centerline{display:none}}
    /* Shared header chrome and a bounded editor keep actions out of the scroll area. */
    .block-container{padding-top:1.2rem;padding-bottom:2rem}
    [data-testid='stAppDeployButton']{display:none}
    .st-key-app_header{padding:.6rem 1rem;border:1px solid #263c52;border-radius:16px;background:linear-gradient(110deg,#12233b,#0c1626)}
    .top-brand{min-height:72px;padding:0;border:0;border-radius:0;background:none;gap:.6rem}
    .top-brand h1{font-size:1.65rem}.top-brand p{font-size:.75rem}.top-brand .eyebrow{font-size:.6rem}
    .header-aircraft{min-height:72px;padding:.3rem .7rem;border:0;border-left:1px solid #263c52;background:none}
    .header-aircraft strong{font-size:.85rem}
    .st-key-app_header .stButton>button,.st-key-app_header [data-testid='stPopover'] button,.st-key-open_scenario_data button{min-height:42px!important;border-radius:10px!important;background:#101f33!important;border-color:#29415c!important;color:#c4eaff!important}
    div[data-testid='stPopover']>button{min-height:42px!important;border-radius:10px!important}
    .st-key-scenario_scroll{height:calc(100dvh - 245px)!important;min-height:240px;padding:1rem!important;scroll-padding-bottom:1rem}
    .st-key-scenario_actions{position:relative;left:auto;bottom:auto;transform:none;width:100%;margin:0;padding:.7rem 1rem;box-sizing:border-box;z-index:5}
    .kpi-grid{gap:.8rem;margin:.5rem 0 1rem}.kpi-tile{min-height:125px;padding:.9rem 1rem}.kpi-tile>strong{font-size:1.5rem}
    .deck-bay{min-height:90px}.deck-bay em{position:static;align-self:flex-end;margin-top:.25rem}
    .deck-heading{flex-wrap:wrap}.deck-legend{white-space:normal}.deck-shell{padding:1rem}
    .st-key-docs_content{padding:1rem;background:#0d1929}
    .pipeline-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.8rem;margin:1rem 0}
    .pipeline-step{padding:1rem;border-top:2px solid #38bdf8;background:#101e30;border-radius:8px}
    .workflow-bar{display:flex;align-items:center;justify-content:space-between;gap:8px;background:#0d1826;border:1px solid #1e314b;border-radius:12px;padding:9px 18px;margin:10px 0 16px}
    .workflow-step{display:flex;align-items:center;gap:7px;font-size:.83rem}
    .step-badge{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;font-size:.72rem;font-weight:700}
    .step-pending .step-badge{background:#162335;color:#64748b;border:1px solid #273e5a}
    .step-pending .step-label{color:#64748b}
    .step-active .step-badge{background:#0284c7;color:#fff;box-shadow:0 0 10px rgba(2,132,199,.45)}
    .step-active .step-label{color:#38bdf8;font-weight:700}
    .step-completed .step-badge{background:#10b981;color:#fff}
    .step-completed .step-label{color:#a7f3d0}
    .workflow-arrow{color:#273e5a;font-size:.85rem}
    @media(max-width:850px){.pipeline-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.st-key-app_header [data-testid='stHorizontalBlock']{flex-wrap:wrap}.st-key-scenario_scroll{height:calc(100dvh - 340px)!important}.header-aircraft{border:0}.kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.workflow-bar{flex-wrap:wrap;gap:6px}}
    @media(max-width:550px){.pipeline-grid{grid-template-columns:1fr}.st-key-scenario_actions [data-testid='stColumn']:first-child{display:none}.st-key-scenario_actions [data-testid='stHorizontalBlock']{flex-wrap:nowrap}.st-key-scenario_actions [data-testid='stColumn']{min-width:0!important;flex:1}.st-key-scenario_scroll{height:55dvh!important}.kpi-tile>strong{font-size:1.25rem}.workflow-step{font-size:.75rem}}
    </style>
    """
